pe": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a3c2b1a6cf242bf4514a4d6934756f84abb3c1ce/content/books/zizhi-tongjian/vol-293/year-0957/part-01/sources/library/xinwudaishi-70-tianhui-era/source.txt", "note": "《新五代史》卷七十，段落 xin-wudaishi-b08f244b9241-p003455；EPUB电子本，纸本及异文待核", "id": "6141462a-c62b-50df-8c9d-ce22db042154"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "张湜", "aliases": ["張湜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周侍御史知杂事。957年受命与同僚解释旧律令、整理繁杂格敕，详定《刑统》。《旧五代史》记其同修者合计十人，具体完成日未载。生卒年未载。", "biography": null, "status": "draft", "id": "b4d58dc9-bca3-5c35-b91d-52b667f355f7"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "郭廷谓", "aliases": ["郭廷謂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭城人，南唐濠州都监。957年率水军溯淮欲烧浮桥，被赵匡赞伏兵击败。生卒年未载。", "biography": null, "status": "draft", "id": "19bb918a-ace7-5a46-9480-796bbc67a61a"}, {"name": "武行德", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州榆次人。947年受契丹命运送晋朝铠甲兵器，途中与军士夺取兵器、杀契丹监军，继而占据河阳。生卒年尚未录入。", "biography": null, "status": "draft", "id": "e0ed92f8-edb4-574b-83af-85088429a093"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李氏（孟昶母）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：李氏（孟昶母），仁赞之母亲。", "biography": null, "status": "draft", "id": "da556260-49fd-5099-b0e4-5003f3d35b65"}, {"name": "王昭远", "aliases": ["王昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "成都人，后蜀官员。年少时跟随僧人智諲进入孟知祥府中，后来被留下侍奉孟昶；《新五代史》《宋史》记当时十三岁。948年由茶酒库使任通奏使、知枢密院事，获委机务和府库财物支配。没有据十三岁反推出生年。", "biography": null, "status": "draft", "id": "49c83873-4e4d-515e-9f4b-ebbf460d53fd"}, {"name": "伊审征", "aliases": ["伊審徵", "伊审徵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀官员，太原人，《宋史》称伊审徵、字申图，记为并州人。951年由前云安榷盐使任通奏使、知枢密院事。关于母亲及其父婚配，两书叙述不同，具体对应仍待校核。生卒年尚未录入。", "biography": null, "status": "draft", "id": "a1611515-927b-50be-b3e4-084a6ff72a62"}, {"name": "韩保贞", "aliases": ["韓保貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩保贞，丰德库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "7090cd80-1efa-59ab-9b8f-05f88da57d52"}, {"name": "赵崇韬", "aliases": ["趙崇韜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀客省使。955年五月，孟昶任命他为北路行营都监，参与抵御后周军的部署。生卒年未载。", "biography": null, "status": "draft", "id": "ac2d7f68-da6e-560c-8f7c-7521a8bbffce"}, {"name": "高彦俦", "aliases": ["高彥儔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高彦俦，太原人、昭武都监、拟领兵者。", "biography": null, "status": "draft", "id": "b335c31e-ee43-595d-8eb5-e601824ba527"}, {"name": "王祚", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王溥的父亲。历任华州刺史，957年六月获任颍州团练使。《宋史》记其早年办盐铁与粮草，后任地方官，整顿租税、疏通水渠。各项治理时间另依传记，不全算957年。生卒年未载。", "biography": null, "status": "draft", "id": "f6c2ea23-cd7a-59d0-a18d-7ffe24fa6557"}, {"name": "王溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王溥。", "biography": null, "status": "draft", "id": "b8b4ff87-1c1f-5c80-bc6c-83b5a3b1164f"}, {"name": "李继勋（后周宋初将领）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大名元城人，后周侍卫步军都指挥使、彰信节度使。956年六月驻寿州城南，被刘仁赡趁无备突击，南寨受损。《宋史》记其早年在郭威帐下任禁军官。与947年后蜀同名左千牛卫上将军缺少同人证据，分别保存。", "biography": null, "status": "draft", "id": "5f69fa08-5e14-59cf-aa6f-05cbc3b5001b"}, {"name": "刘承钧", "aliases": ["劉承鈞", "刘钧", "劉鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "王朴", "aliases": ["王樸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "东平人，原任校书郎。951年任柴荣镇宁军掌书记。《旧五代史》记他字文伯，在后汉乾祐年间中进士，后来进入澶州幕府。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aef64c13-19ef-556c-96f1-dd9e8fb91844"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

