SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "柴荣命张湜等解释律令、整理格敕，详定《刑统》", "start_year": 957, "end_year": 957, "time_original": "957年五月条所记，具体下诏日未载", "dynasty": "五代十国", "description": "柴荣命张湜等解释律令、整理格敕，详定《刑统》。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d1c0d1d7-6163-5ab8-beeb-e0420f1c84c0"}, {"title": "郭廷谓率水军切断涡口浮桥", "start_year": 957, "end_year": 957, "time_original": "957年五月条之后、六月条之前，具体日未载", "dynasty": "五代十国", "description": "郭廷谓率水军切断涡口浮桥。", "phases": [], "location_name": "涡口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "72d3345c-1f92-5ae6-8e64-0f52d72d8da5"}, {"title": "郭廷谓袭败定远周军，武行德仅以身免", "start_year": 957, "end_year": 957, "time_original": "957年五月至六月条间，具体战日未载", "dynasty": "五代十国", "description": "郭廷谓袭败定远周军，武行德仅以身免。", "phases": [], "location_name": "定远", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f745b72c-6677-54d3-bd5e-11ade95ccdea"}, {"title": "李璟任郭廷谓为滁州团练使、上淮水陆应援使", "start_year": 957, "end_year": 957, "time_original": "957年定远获胜以后，具体授任日未载", "dynasty": "五代十国", "description": "李璟任郭廷谓为滁州团练使、上淮水陆应援使。", "phases": [], "location_name": "滁州、上淮", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3d27e33a-81bc-586c-b192-4b46f266a8d5"}, {"title": "李廷珪因败战遭批评，自己也请求解除军职", "start_year": 957, "end_year": 957, "time_original": "